export default {"file":"index.html","title":"Schoolix - Sign In","htmlClass":"","bodyClass":"sx-login-app auth-checking","body":"\r\n<div id=\"sxPageLoader\" class=\"sx-page-loader\" role=\"status\" aria-live=\"polite\">\r\n  <section class=\"dots-container\" aria-label=\"Loading page\">\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n  </section>\r\n</div>\r\n\r\n<div class=\"auth-gate\" id=\"authGate\" role=\"status\" aria-live=\"polite\">\r\n        <div class=\"auth-loader-card\">\r\n        <div class=\"auth-loader-mark\">\r\n            <img src=\"/schoolix-app-icon.svg\" alt=\"Schoolix logo\">\r\n        </div>\r\n        <div>\r\n            <div class=\"auth-loader-title\">Opening Schoolix</div>\r\n            <div class=\"auth-loader-subtitle\" id=\"authGateText\">Checking your saved login...</div>\r\n        </div>\r\n        <div class=\"auth-loader-ring\"><span></span></div>\r\n    </div>\r\n</div>\r\n\r\n<main class=\"shell\">\r\n\r\n    <header class=\"mobile-brand\" aria-label=\"Schoolix\">\r\n        <div class=\"mobile-brand-logo\">\r\n            <div class=\"brand-icon\" style=\"width:32px;height:32px;border-radius:10px;\">\r\n                <img src=\"/schoolix-app-icon.svg\" alt=\"\">\r\n            </div>\r\n            Schoolix\r\n        </div>\r\n        <span class=\"mobile-brand-tag\">Sign in</span>\r\n    </header>\r\n\r\n    <!-- LEFT PANEL -->\r\n    <div class=\"panel-left\">\r\n        <div class=\"orb orb-1\"></div>\r\n        <div class=\"orb orb-2\"></div>\r\n        <div class=\"orb orb-3\"></div>\r\n        <div class=\"grid-overlay\"></div>\r\n\r\n        <div class=\"panel-left-content\">\r\n            <!-- Brand -->\r\n            <div class=\"brand-logo\">\r\n                <div class=\"brand-icon\">\r\n                    <img src=\"/schoolix-app-icon.svg\" alt=\"\">\r\n                </div>\r\n                Schoolix\r\n            </div>\r\n\r\n            <!-- Hero -->\r\n            <div class=\"left-hero\">\r\n                <div class=\"hero-tag\">\r\n                    <span class=\"hero-tag-dot\"></span>\r\n                    School ERP Platform\r\n                </div>\r\n                <h1 class=\"hero-heading\">\r\n                    Empowering<br>\r\n                    <span>Education,</span><br>\r\n                    Simplified.\r\n                </h1>\r\n                <p class=\"hero-desc\">\r\n                    A practical workspace for admissions, attendance, fees, reports, teachers, and transport.\r\n                </p>\r\n\r\n                <div class=\"stats-row\">\r\n                    <div class=\"stat-item\">\r\n                        <span class=\"stat-num\">500+</span>\r\n                        <span class=\"stat-label\">Schools</span>\r\n                    </div>\r\n                    <div class=\"stat-divider\"></div>\r\n                    <div class=\"stat-item\">\r\n                        <span class=\"stat-num\">1.2L+</span>\r\n                        <span class=\"stat-label\">Students</span>\r\n                    </div>\r\n                    <div class=\"stat-divider\"></div>\r\n                    <div class=\"stat-item\">\r\n                        <span class=\"stat-num\">24/7</span>\r\n                        <span class=\"stat-label\">Access</span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <!-- Dots -->\r\n            <div class=\"dots-row\">\r\n                <div class=\"dot\"></div>\r\n                <div class=\"dot\"></div>\r\n                <div class=\"dot active\"></div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n\r\n    <!-- RIGHT PANEL -->\r\n    <div class=\"panel-right\">\r\n        <div class=\"form-card\">\r\n\r\n            <div class=\"form-header\">\r\n                <p class=\"form-welcome\">Welcome back</p>\r\n                <h2 class=\"form-title\">Sign In</h2>\r\n                <p class=\"form-subtitle\">Access your dashboard using your school credentials.</p>\r\n\r\n                <div class=\"form-hint\">\r\n                    <span class=\"form-hint-icon\">\r\n                        <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm1 15h-2v-6h2v6zm0-8h-2V7h2v2z\"/></svg>\r\n                    </span>\r\n                    <p>Use your <strong style=\"color:#c4b5fd;font-weight:600;\">email</strong>, parent email, or <strong style=\"color:#c4b5fd;font-weight:600;\">Student ID</strong> to continue.</p>\r\n                </div>\r\n            </div>\r\n\r\n            <form id=\"loginForm\" novalidate>\r\n                <div class=\"field\">\r\n                    <label class=\"field-label\" for=\"email\">Email Address / Student ID</label>\r\n                    <div class=\"field-wrap\">\r\n                        <input\r\n                            class=\"field-input\"\r\n                            type=\"text\"\r\n                            id=\"email\"\r\n                            placeholder=\"Enter email or Student ID\"\r\n                            autocomplete=\"username\"\r\n                            required\r\n                        >\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"field\">\r\n                    <label class=\"field-label\" for=\"password\">Password</label>\r\n                    <div class=\"field-wrap\">\r\n                        <input\r\n                            class=\"field-input\"\r\n                            type=\"password\"\r\n                            id=\"password\"\r\n                            placeholder=\"Enter your password\"\r\n                            autocomplete=\"current-password\"\r\n                            required\r\n                        >\r\n                        <button\r\n                            type=\"button\"\r\n                            class=\"field-suffix toggle-password\"\r\n                            id=\"togglePassword\"\r\n                            aria-label=\"Show password\"\r\n                            aria-pressed=\"false\"\r\n                            title=\"Show password\"\r\n                        >\r\n                            <svg id=\"eyeIcon\" viewBox=\"0 0 24 24\" aria-hidden=\"true\">\r\n                                <path d=\"M12 5c-5.5 0-10 4.5-11 7 1 2.5 5.5 7 11 7s10-4.5 11-7c-1-2.5-5.5-7-11-7Zm0 11.5A4.5 4.5 0 1 1 12 7a4.5 4.5 0 0 1 0 9.5Zm0-2A2.5 2.5 0 1 0 12 9a2.5 2.5 0 0 0 0 5Z\"/>\r\n                            </svg>\r\n                        </button>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"forgot-row\">\r\n                    <a href=\"#\" class=\"forgot-link\" onclick=\"resetPassword(); return false;\">Forgot password?</a>\r\n                </div>\r\n\r\n                <button type=\"submit\" class=\"btn-primary\">Sign In</button>\r\n            </form>\r\n\r\n            <div class=\"loading-bar\" id=\"loading\"></div>\r\n\r\n            <div class=\"error-msg\" id=\"errorMsg\">\r\n                <span class=\"error-msg-icon\">\r\n                    <svg viewBox=\"0 0 24 24\"><path d=\"M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm1 15h-2v-2h2v2zm0-4h-2V7h2v6z\"/></svg>\r\n                </span>\r\n                <p id=\"errorText\"></p>\r\n            </div>\r\n\r\n            <div class=\"or-row\">\r\n                <div class=\"or-line\"></div>\r\n                <span class=\"or-text\">or continue with</span>\r\n                <div class=\"or-line\"></div>\r\n            </div>\r\n\r\n            <button class=\"btn-google\" onclick=\"loginWithGoogle()\">\r\n                <svg class=\"google-svg\" viewBox=\"0 0 48 48\">\r\n                    <path fill=\"#EA4335\" d=\"M24 9.5c3.54 0 6.71 1.22 9.21 3.6l6.85-6.85C35.9 2.38 30.47 0 24 0 14.62 0 6.51 5.38 2.56 13.22l7.98 6.19C12.43 13.72 17.74 9.5 24 9.5z\"/>\r\n                    <path fill=\"#4285F4\" d=\"M46.98 24.55c0-1.57-.15-3.09-.38-4.55H24v9.02h12.94c-.58 2.96-2.26 5.48-4.78 7.18l7.73 6c4.51-4.18 7.09-10.36 7.09-17.65z\"/>\r\n                    <path fill=\"#FBBC05\" d=\"M10.53 28.59c-.48-1.45-.76-2.99-.76-4.59s.27-3.14.76-4.59l-7.98-6.19C.92 16.46 0 20.12 0 24c0 3.88.92 7.54 2.56 10.78l7.97-6.19z\"/>\r\n                    <path fill=\"#34A853\" d=\"M24 48c6.48 0 11.93-2.13 15.89-5.81l-7.73-6c-2.15 1.45-4.92 2.3-8.16 2.3-6.26 0-11.57-4.22-13.47-9.91l-7.98 6.19C6.51 42.62 14.62 48 24 48z\"/>\r\n                    <path fill=\"none\" d=\"M0 0h48v48H0z\"/>\r\n                </svg>\r\n                Continue with Google\r\n            </button>\r\n\r\n            <a class=\"btn-apk\" id=\"downloadAndroidApp\" href=\"/dist/Schoolix-download\" download=\"Schoolix.apk\">\r\n                <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">\r\n                    <path d=\"M12 3v12\"/><path d=\"m7 10 5 5 5-5\"/><path d=\"M5 21h14\"/>\r\n                </svg>\r\n                <span id=\"downloadAndroidLabel\">Download Android App</span>\r\n            </a>\r\n            <span class=\"download-meta\" id=\"downloadAndroidMeta\">Latest APK</span>\r\n\r\n        </div>\r\n    </div>\r\n</main>\r\n\r\n<script src=\"school-branding.js\" defer></script>\r\n<script src=\"/schoolix-app.js?v=navbar-20260721\" defer></script>\r\n<script type=\"module\">\r\nimport { initializeApp } from \"./firebase-compat.js\";\r\nimport {\r\n    getAuth,\r\n    signInWithEmailAndPassword,\r\n    signInWithPopup,\r\n    signInWithRedirect,\r\n    getRedirectResult,\r\n    signInWithCredential,\r\n    GoogleAuthProvider,\r\n    onAuthStateChanged,\r\n    signOut\r\n} from \"./firebase-compat.js\";\r\nimport {\r\n    getFirestore,\r\n    doc,\r\n    getDoc,\r\n    getDocs,\r\n    collection,\r\n    query,\r\n    where,\r\n    limit,\r\n    setDoc\r\n} from \"./firebase-compat.js\";\r\n\r\nconst firebaseConfig = {\r\n    apiKey: \"AIzaSyAomGwef93HFT9Xyx7SVW95FPw_IcIAICE\",\r\n    authDomain: \"schoolix-48107.firebaseapp.com\",\r\n    projectId: \"schoolix-48107\"\r\n};\r\n\r\nconst app = initializeApp(firebaseConfig);\r\nconst auth = getAuth(app);\r\nconst db = getFirestore(app);\r\nconst googleProvider = new GoogleAuthProvider();\r\ngoogleProvider.setCustomParameters({ prompt: \"select_account\" });\r\n\r\nconst SUPABASE_URL = \"https://ezkmeedcqetztkeppxil.supabase.co\";\r\nconst SUPABASE_ANON_KEY = \"eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImV6a21lZWRjcWV0enRrZXBweGlsIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzgxMjk5NjAsImV4cCI6MjA5MzcwNTk2MH0.1davJ_NYkFhHToUtcFBR0kA6dk0-cOkaIbK2SCObkQg\";\r\nconst PASSWORD_RESET_FUNCTION_URL = `${SUPABASE_URL}/functions/v1/send-password-reset-email`;\r\n\r\nconst loginForm = document.getElementById('loginForm');\r\nconst emailInput = document.getElementById('email');\r\nconst passwordInput = document.getElementById('password');\r\nconst loadingEl = document.getElementById('loading');\r\nconst errorEl = document.getElementById('errorMsg');\r\nconst errorText = document.getElementById('errorText');\r\nconst togglePasswordBtn = document.getElementById('togglePassword');\r\nconst eyeIcon = document.getElementById('eyeIcon');\r\nconst downloadAndroidApp = document.getElementById('downloadAndroidApp');\r\nconst downloadAndroidLabel = document.getElementById('downloadAndroidLabel');\r\nconst downloadAndroidMeta = document.getElementById('downloadAndroidMeta');\r\nconst authGate = document.getElementById('authGate');\r\nconst authGateText = document.getElementById('authGateText');\r\nlet authRedirectInProgress = false;\r\nlet nativeGoogleResolve = null;\r\nlet nativeGoogleReject = null;\r\n\r\nconst STUDENT_SESSION_KEY = \"schoolixStudentSession\";\r\nconst TEACHER_SESSION_KEY = \"schoolixTeacherSession\";\r\nconst SUPER_ADMIN_EMAIL = \"anshbajpai4@gmail.com\";\r\n\r\nfunction loadStudentSession() {\r\n    try { return JSON.parse(localStorage.getItem(STUDENT_SESSION_KEY)); } catch { return null; }\r\n}\r\nfunction saveStudentSession(data) {\r\n    localStorage.setItem(STUDENT_SESSION_KEY, JSON.stringify(data));\r\n}\r\nfunction clearStudentSession() {\r\n    localStorage.removeItem(STUDENT_SESSION_KEY);\r\n}\r\n\r\nfunction loadTeacherSession() {\r\n    try { return JSON.parse(localStorage.getItem(TEACHER_SESSION_KEY)); } catch { return null; }\r\n}\r\nfunction saveTeacherSession(session) {\r\n    if (!session) return;\r\n    try {\r\n        const json = JSON.stringify(session);\r\n        localStorage.setItem(TEACHER_SESSION_KEY, json);\r\n        localStorage.setItem(\"schoolixLastTeacherProfile\", json);\r\n        if (session.uid) {\r\n            localStorage.setItem(`schoolixTeacherProfile_${session.uid}`, json);\r\n        }\r\n        if (session.email) {\r\n            localStorage.setItem(`schoolixTeacherProfileEmail_${String(session.email).trim().toLowerCase()}`, json);\r\n        }\r\n        const schoolId = session.schoolId || session.adminId || \"\";\r\n        if (schoolId) {\r\n            localStorage.setItem(\"teacherSchoolId\", schoolId);\r\n            if (session.schoolName) {\r\n                localStorage.setItem(`schoolixSchoolName_${schoolId}`, session.schoolName);\r\n            }\r\n        }\r\n        if (session.schoolName) {\r\n            window.SchoolBranding?.persistSchoolName?.(session.schoolName);\r\n            try { localStorage.setItem(\"schoolix.schoolName\", session.schoolName); } catch {}\r\n        }\r\n        if (session.logoUrl) {\r\n            window.SchoolBranding?.persistSchoolLogo?.(session.logoUrl);\r\n        }\r\n        if (session.section) {\r\n            localStorage.setItem(\"teacherSection\", session.section);\r\n        }\r\n    } catch (e) {\r\n        console.warn(\"Unable to save teacher session:\", e);\r\n    }\r\n}\r\nfunction clearTeacherSession() {\r\n    try {\r\n        localStorage.removeItem(TEACHER_SESSION_KEY);\r\n        localStorage.removeItem(\"schoolixLastTeacherProfile\");\r\n    } catch {}\r\n}\r\n\r\nfunction userFacingAuthError(error, fallback = \"Login failed. Please try again.\") {\r\n    const code = String(error?.code || \"\").toLowerCase();\r\n    const messages = {\r\n        \"auth/user-not-found\": \"The email or password is incorrect.\",\r\n        \"auth/wrong-password\": \"The email or password is incorrect.\",\r\n        \"auth/invalid-credential\": \"The email or password is incorrect.\",\r\n        \"auth/invalid-credentials\": \"The email or password is incorrect.\",\r\n        \"auth/invalid-email\": \"Enter a valid email address.\",\r\n        \"auth/too-many-requests\": \"Too many attempts. Please wait a moment and try again.\",\r\n        \"network-request-failed\": \"Network connection failed. Check your internet and try again.\",\r\n        \"deadline-exceeded\": \"The request took too long. Check your connection and try again.\",\r\n        \"unavailable\": \"Schoolix is temporarily unavailable. Please try again shortly.\"\r\n    };\r\n    return messages[code] || window.SchoolixErrors?.message?.(error, fallback) || fallback;\r\n}\r\n\r\nasync function requestPasswordResetEmail(email) {\r\n    const controller = new AbortController();\r\n    const timeoutId = setTimeout(() => controller.abort(), 20000);\r\n    try {\r\n        const response = await fetch(PASSWORD_RESET_FUNCTION_URL, {\r\n            method: \"POST\",\r\n            headers: {\r\n                \"Content-Type\": \"application/json\",\r\n                \"apikey\": SUPABASE_ANON_KEY,\r\n                \"Authorization\": `Bearer ${SUPABASE_ANON_KEY}`\r\n            },\r\n            body: JSON.stringify({\r\n                email,\r\n                schoolName: window.SchoolBranding?.getSchoolName() || \"Schoolix\"\r\n            }),\r\n            signal: controller.signal\r\n        });\r\n        if (!response.ok) {\r\n            const error = new Error(\"Password reset email could not be sent.\");\r\n            error.code = response.status === 429 ? \"resource-exhausted\" : response.status >= 500 ? \"unavailable\" : \"unknown\";\r\n            throw error;\r\n        }\r\n    } catch (error) {\r\n        if (error.name === \"AbortError\") {\r\n            const timeoutError = new Error(\"Password reset request timed out.\");\r\n            timeoutError.code = \"deadline-exceeded\";\r\n            throw timeoutError;\r\n        }\r\n        throw error;\r\n    } finally {\r\n        clearTimeout(timeoutId);\r\n    }\r\n}\r\n\r\nfunction linkedSchoolId(profile = {}, adminData = null) {\r\n    return String(\r\n        profile.schoolId || profile.schoolID || profile.schoolUid || profile.schoolUID || profile.schoolDocId || profile.schoolDocID ||\r\n        profile.adminId || profile.adminID || profile.adminUid || profile.adminUID || profile.adminDocId || profile.adminDocID ||\r\n        adminData?.schoolId || adminData?.schoolID || adminData?.schoolUid || adminData?.schoolUID ||\r\n        adminData?.adminId || adminData?.adminID || adminData?.adminUid || adminData?.adminUID ||\r\n        adminData?.schoolDocId || adminData?.schoolDocID || adminData?.adminDocId || adminData?.adminID || adminData?.id || \"\"\r\n    ).trim();\r\n}\r\n\r\nfunction buildStudentSession(user, student = {}, adminData = null, extra = {}) {\r\n    const schoolId = linkedSchoolId(student, adminData);\r\n    const schoolName = student.schoolName || adminData?.schoolName || window.SchoolBranding?.getSchoolName?.() || \"\";\r\n    return {\r\n        uid: user.uid,\r\n        authUid: user.supabaseUid || user.uid,\r\n        supabaseAuthUid: user.supabaseUid || \"\",\r\n        studentId: student.studentId || student.id || user.uid,\r\n        studentDocId: student.studentDocId || student.id || \"\",\r\n        name: student.name || student.fullName || student.studentName || \"\",\r\n        class: student.class || \"\",\r\n        section: student.section || \"\",\r\n        rollNo: student.rollNo || student.roll || \"\",\r\n        email: student.email || student.authEmail || user.email || \"\",\r\n        schoolId,\r\n        schoolName,\r\n        role: \"student\",\r\n        loginAt: new Date().toISOString(),\r\n        ...extra\r\n    };\r\n}\r\n\r\nfunction buildTeacherSession(user, teacher = {}, adminData = null, extra = {}) {\r\n    const schoolId = linkedSchoolId(teacher, adminData);\r\n    const schoolName = teacher.schoolName || adminData?.schoolName || adminData?.instituteName || window.SchoolBranding?.getSchoolName?.() || \"\";\r\n    const logoUrl = teacher.logoUrl || teacher.schoolLogoUrl || adminData?.logoUrl || adminData?.schoolLogoUrl || \"\";\r\n    const photoUrl = teacher.photoUrl || teacher.imageUrl || teacher.profilePhotoUrl || teacher.avatarUrl || \"\";\r\n    const name = teacher.name || teacher.fullName || teacher.teacherName || teacher.displayName || user.displayName || \"\";\r\n    return {\r\n        uid: user.uid,\r\n        authUid: user.supabaseUid || user.uid,\r\n        supabaseAuthUid: user.supabaseUid || \"\",\r\n        docId: teacher.id || user.uid,\r\n        teacherId: teacher.teacherId || teacher.staffId || teacher.id || \"\",\r\n        name,\r\n        displayName: name,\r\n        email: teacher.email || teacher.authEmail || user.email || \"\",\r\n        class: teacher.class || \"\",\r\n        section: teacher.section || \"\",\r\n        assignedClasses: teacher.assignedClasses || [],\r\n        schoolId,\r\n        adminId: schoolId,\r\n        schoolName,\r\n        logoUrl,\r\n        photoUrl,\r\n        role: \"teacher\",\r\n        loginAt: new Date().toISOString(),\r\n        ...extra\r\n    };\r\n}\r\n\r\nconst FEATURE_LABELS = {\r\n    dashboard: \"Dashboard\",\r\n    teachers: \"Teachers\",\r\n    students: \"Students\",\r\n    attendance: \"Attendance\",\r\n    payroll: \"Payroll\",\r\n    reports: \"Reports\",\r\n    announcements: \"Announcements\",\r\n    settings: \"Settings\"\r\n};\r\n\r\nasync function hydrateAndroidDownloadLink() {\r\n    if (!downloadAndroidApp) return;\r\n    const fallbackUrl = \"/dist/Schoolix-download\";\r\n    try {\r\n        const response = await fetch(`/version.json?t=${Date.now()}`, { cache: \"no-store\" });\r\n        if (!response.ok) throw new Error(\"version.json unavailable\");\r\n        const data = await response.json();\r\n        const apkUrl = String(data.apkUrl || fallbackUrl).trim();\r\n        downloadAndroidApp.href = apkUrl || fallbackUrl;\r\n        if (downloadAndroidLabel) downloadAndroidLabel.textContent = \"Download Latest Android App\";\r\n        if (downloadAndroidMeta) {\r\n            const versionName = data.versionName ? `v${data.versionName}` : \"Latest version\";\r\n            const versionCode = data.versionCode ? ` build ${data.versionCode}` : \"\";\r\n            downloadAndroidMeta.textContent = `${versionName}${versionCode}`;\r\n        }\r\n    } catch (error) {\r\n        console.warn(\"Unable to load APK metadata:\", error);\r\n        downloadAndroidApp.href = fallbackUrl;\r\n        if (downloadAndroidMeta) downloadAndroidMeta.textContent = \"Latest APK\";\r\n    }\r\n}\r\n\r\nfunction scheduleAndroidDownloadHydration() {\r\n    const run = () => {\r\n        if (\"requestIdleCallback\" in window) window.requestIdleCallback(() => hydrateAndroidDownloadLink(), { timeout: 3000 });\r\n        else setTimeout(() => hydrateAndroidDownloadLink(), 1500);\r\n    };\r\n    if (document.readyState === \"complete\") run();\r\n    else window.addEventListener(\"load\", run, { once: true });\r\n}\r\n\r\nscheduleAndroidDownloadHydration();\r\n\r\nfunction accessErrorFor(adminData, featureKey = \"\") {\r\n    if (!adminData || adminData.access === false) {\r\n        return \"Your school's platform access has been disabled by the Super Admin. Please contact support.\";\r\n    }\r\n    if (featureKey && (adminData.features || {})[featureKey] === false) {\r\n        return `${FEATURE_LABELS[featureKey] || \"This\"} access has been disabled for your school by the Super Admin.`;\r\n    }\r\n    return \"\";\r\n}\r\n\r\nasync function getAdminAccessData(userId, userData) {\r\n    if (!userData) return null;\r\n    if ((userData.role || \"\").toLowerCase() === \"admin\") return { id: userId, ...userData };\r\n    const adminId = linkedSchoolId(userData);\r\n    if (!adminId) return null;\r\n    try {\r\n        const adminSnap = await getDoc(doc(db, \"users\", adminId));\r\n        return adminSnap.exists() ? { id: adminSnap.id, ...adminSnap.data() } : null;\r\n    } catch (error) {\r\n        console.warn(\"Unable to load admin access profile\", error);\r\n        return null;\r\n    }\r\n}\r\n\r\nconst EYE_OPEN = `<path d=\"M12 5c-5.5 0-10 4.5-11 7 1 2.5 5.5 7 11 7s10-4.5 11-7c-1-2.5-5.5-7-11-7Zm0 11.5A4.5 4.5 0 1 1 12 7a4.5 4.5 0 0 1 0 9.5Zm0-2A2.5 2.5 0 1 0 12 9a2.5 2.5 0 0 0 0 5Z\"/>`;\r\nconst EYE_CLOSED = `<path d=\"M2.1 3.51 3.51 2.1l18.38 18.38-1.41 1.41-3.3-3.3A10.96 10.96 0 0 1 12 21C6.5 21 2 16.5 1 14c.52-1.31 1.63-2.97 3.22-4.49l-.21-.21A.99.99 0 0 1 2.1 3.51ZM12 7c2.76 0 5 2.24 5 5 0 .62-.11 1.21-.32 1.76l-1.6-1.6A2.97 2.97 0 0 0 12 9c-.7 0-1.34.24-1.85.64L8.79 8.28A4.97 4.97 0 0 1 12 7Zm0 10c-2.76 0-5-2.24-5-5 0-.74.16-1.45.43-2.08L5.37 8.86C4 10.12 3.1 11.42 2.78 12c1 2.09 4.59 6 9.22 6 1.11 0 2.17-.18 3.14-.5l-1.69-1.69c-.45.12-.93.19-1.45.19Zm5.63-2.69 1.48 1.48C20.48 14.93 21.48 13.46 21.9 12c-1-2.5-5.5-7-9.9-7-1.25 0-2.46.23-3.56.65l1.56 1.56c.62-.14 1.28-.21 1.98-.21 2.76 0 5 2.24 5 5 0 .47-.07.92-.2 1.31Z\"/>`;\r\n\r\ntogglePasswordBtn.addEventListener('click', () => {\r\n    const isHidden = passwordInput.type === \"password\";\r\n    passwordInput.type = isHidden ? \"text\" : \"password\";\r\n    eyeIcon.innerHTML = isHidden ? EYE_CLOSED : EYE_OPEN;\r\n    togglePasswordBtn.setAttribute(\"aria-label\", isHidden ? \"Hide password\" : \"Show password\");\r\n    togglePasswordBtn.setAttribute(\"aria-pressed\", String(isHidden));\r\n});\r\n\r\nfunction showError(message) {\r\n    errorText.textContent = message;\r\n    errorEl.classList.add('visible');\r\n    setTimeout(() => errorEl.classList.remove('visible'), 5500);\r\n}\r\n\r\nconst accessError = new URLSearchParams(window.location.search).get(\"access_error\");\r\nif (accessError) {\r\n    showError(accessError);\r\n    history.replaceState({}, document.title, window.location.pathname);\r\n}\r\n\r\nfunction showLoading(show) {\r\n    loadingEl.classList.toggle('visible', show);\r\n    loginForm.style.opacity = show ? '0.65' : '1';\r\n    loginForm.style.pointerEvents = show ? 'none' : '';\r\n}\r\n\r\nfunction setAuthGate(message) {\r\n    if (authGateText && message) authGateText.textContent = message;\r\n    document.body.classList.add(\"auth-checking\");\r\n    authGate?.classList.remove(\"hidden\");\r\n}\r\n\r\nfunction hideAuthGate() {\r\n    document.body.classList.remove(\"auth-checking\");\r\n    authGate?.classList.add(\"hidden\");\r\n}\r\n\r\nfunction isNativeSchoolixApp() {\r\n    try {\r\n        if (window.Capacitor?.isNativePlatform?.()) return true;\r\n        return location.protocol === \"capacitor:\";\r\n    } catch {\r\n        return false;\r\n    }\r\n}\r\n\r\nfunction signInWithNativeGoogle() {\r\n    return new Promise((resolve, reject) => {\r\n        if (!window.SchoolixNativeAuth?.signInWithGoogle) {\r\n            reject(new Error(\"Native Google login is not available\"));\r\n            return;\r\n        }\r\n        nativeGoogleResolve = resolve;\r\n        nativeGoogleReject = reject;\r\n        window.SchoolixNativeAuth.signInWithGoogle();\r\n    });\r\n}\r\n\r\nwindow.SchoolixNativeGoogleAuth = {\r\n    async receiveIdToken(idToken) {\r\n        try {\r\n            const token = String(idToken || \"\").trim();\r\n            if (!token) throw new Error(\"Google login token was not received\");\r\n            const credential = GoogleAuthProvider.credential(token);\r\n            const result = await signInWithCredential(auth, credential);\r\n            nativeGoogleResolve?.(result);\r\n        } catch (error) {\r\n            nativeGoogleReject?.(error);\r\n        } finally {\r\n            nativeGoogleResolve = null;\r\n            nativeGoogleReject = null;\r\n        }\r\n    },\r\n    receiveError(message) {\r\n        nativeGoogleReject?.(new Error(message || \"Google login failed\"));\r\n        nativeGoogleResolve = null;\r\n        nativeGoogleReject = null;\r\n    }\r\n};\r\n\r\nfunction isParentIdentifier(identifier, student) {\r\n    const lowered = String(identifier || \"\").trim().toLowerCase();\r\n    if (!lowered || !lowered.includes(\"@\")) return false;\r\n    if (String(student.email || \"\").trim().toLowerCase() === lowered) return false;\r\n    if (String(student.authEmail || \"\").trim().toLowerCase() === lowered) return false;\r\n    return [student.parentEmail, student.fatherEmail, student.motherEmail, student.guardianEmail]\r\n        .some(email => String(email || \"\").trim().toLowerCase() === lowered);\r\n}\r\n\r\nfunction uniqueLookupValues(values = []) {\r\n    const seen = new Set();\r\n    return values\r\n        .map(value => typeof value === \"string\" ? value.trim() : value)\r\n        .filter(value => value !== \"\" && value !== null && value !== undefined)\r\n        .filter(value => {\r\n            const key = `${typeof value}:${String(value)}`;\r\n            if (seen.has(key)) return false;\r\n            seen.add(key);\r\n            return true;\r\n        });\r\n}\r\n\r\nasync function findStudentRecord(identifier, options = {}) {\r\n    const normalized = identifier.trim();\r\n    if (!normalized) return null;\r\n    const lowered = normalized.toLowerCase();\r\n    const uppered = normalized.toUpperCase();\r\n    const idValues = uniqueLookupValues([\r\n        normalized,\r\n        lowered,\r\n        uppered,\r\n        /^\\d+$/.test(normalized) ? Number(normalized) : null\r\n    ]);\r\n\r\n    for (const docId of uniqueLookupValues([normalized, lowered, uppered])) {\r\n        try {\r\n            const byIdDoc = await getDoc(doc(db, \"users\", docId));\r\n            if (byIdDoc.exists() && (byIdDoc.data().role || \"\").toLowerCase() === \"student\") {\r\n                return { id: byIdDoc.id, ...byIdDoc.data() };\r\n            }\r\n        } catch (error) {\r\n            if (error?.code !== \"permission-denied\") console.warn(\"Student direct lookup failed:\", error);\r\n        }\r\n    }\r\n\r\n    const lookups = [\r\n        [\"studentId\", idValues],\r\n        [\"email\", uniqueLookupValues([lowered, normalized])],\r\n        [\"authEmail\", uniqueLookupValues([lowered, normalized])]\r\n    ];\r\n    if (options.parent) {\r\n        const emailValues = uniqueLookupValues([lowered, normalized]);\r\n        lookups.push(\r\n            [\"parentEmail\", emailValues],\r\n            [\"fatherEmail\", emailValues],\r\n            [\"motherEmail\", emailValues],\r\n            [\"guardianEmail\", emailValues]\r\n        );\r\n    }\r\n    for (const [field, values] of lookups) {\r\n        for (const value of values) {\r\n            try {\r\n                const snap = await getDocs(query(\r\n                    collection(db, \"users\"),\r\n                    where(\"role\", \"==\", \"student\"),\r\n                    where(field, \"==\", value),\r\n                    limit(1)\r\n                ));\r\n                if (!snap.empty) return { id: snap.docs[0].id, ...snap.docs[0].data() };\r\n            } catch (error) {\r\n                if (error?.code !== \"permission-denied\") console.warn(`Student ${field} lookup failed:`, error);\r\n            }\r\n        }\r\n    }\r\n    return null;\r\n}\r\n\r\nasync function loginStudent(identifier, password, options = {}) {\r\n    const student = await findStudentRecord(identifier, { parent: true });\r\n    if (!student) return { success: false, reason: \"Student or parent record not found.\" };\r\n    const authEmail = String(student.authEmail || student.email || \"\").trim().toLowerCase();\r\n    if (!authEmail || authEmail.endsWith(\"@schoolix.student\")) {\r\n        return { success: false, reason: \"Registered email is missing for this student. Contact admin to update the student login email.\" };\r\n    }\r\n    const cred = await signInWithEmailAndPassword(auth, authEmail, password);\r\n    const expectedAuthUid = String(student.authUid || \"\").trim();\r\n    const signedInIds = [cred.user.uid, cred.user.supabaseUid].map(value => String(value || \"\").trim()).filter(Boolean);\r\n    const signedInEmail = String(cred.user.email || \"\").trim().toLowerCase();\r\n    const studentEmails = [student.authEmail, student.email]\r\n        .map(value => String(value || \"\").trim().toLowerCase())\r\n        .filter(Boolean);\r\n    if (expectedAuthUid && !signedInIds.includes(expectedAuthUid) && !studentEmails.includes(signedInEmail)) {\r\n        await signOut(auth).catch(() => {});\r\n        return { success: false, reason: \"Student login record is linked to a different account. Contact admin to refresh this student's login.\" };\r\n    }\r\n    const adminData = await getAdminAccessData(cred.user.uid, student);\r\n    const accessReason = accessErrorFor(adminData);\r\n    if (accessReason) {\r\n        await signOut(auth).catch(() => {});\r\n        return { success: false, reason: accessReason };\r\n    }\r\n    if (isParentIdentifier(identifier, student)) {\r\n        saveStudentSession(buildStudentSession(cred.user, student, adminData, {\r\n            loginAs: \"parent\",\r\n            parentEmail: identifier.toLowerCase()\r\n        }));\r\n        window.location.href = \"#/student-dashboard.html\";\r\n        return { success: true };\r\n    }\r\n    saveStudentSession(buildStudentSession(cred.user, student, adminData));\r\n    setAuthGate(\"Opening student dashboard...\");\r\n    window.location.href = \"#/student-dashboard.html\";\r\n    return { success: true };\r\n}\r\n\r\nasync function findSignedInStudentRecord(user) {\r\n    if (!user) return null;\r\n    const uid = String(user.uid || \"\").trim();\r\n    const email = String(user.email || \"\").trim().toLowerCase();\r\n    if (uid) {\r\n        try {\r\n            const snap = await getDocs(query(\r\n                collection(db, \"users\"),\r\n                where(\"role\", \"==\", \"student\"),\r\n                where(\"authUid\", \"==\", uid),\r\n                limit(1)\r\n            ));\r\n            if (!snap.empty) return { id: snap.docs[0].id, ...snap.docs[0].data() };\r\n        } catch (error) {\r\n            if (error?.code !== \"permission-denied\") console.warn(\"Student auth UID lookup failed:\", error);\r\n        }\r\n    }\r\n    return email ? await findStudentRecord(email, { parent: true }) : null;\r\n}\r\n\r\nasync function findSignedInUserRecord(user) {\r\n    if (!user) return null;\r\n    const uid = String(user.uid || \"\").trim();\r\n    const email = String(user.email || \"\").trim().toLowerCase();\r\n    const lookups = [];\r\n    if (uid) lookups.push([\"authUid\", uid], [\"uid\", uid]);\r\n    if (email) lookups.push([\"email\", email], [\"authEmail\", email]);\r\n    for (const [field, value] of lookups) {\r\n        try {\r\n            const snap = await getDocs(query(collection(db, \"users\"), where(field, \"==\", value), limit(1)));\r\n            if (!snap.empty) return { id: snap.docs[0].id, ...snap.docs[0].data() };\r\n        } catch (error) {\r\n            if (error?.code !== \"permission-denied\") console.warn(`Profile ${field} recovery failed:`, error);\r\n        }\r\n    }\r\n    return null;\r\n}\r\n\r\nasync function syncSchoolName(userId, userData) {\r\n    try {\r\n        const branding = window.SchoolBranding;\r\n        if (!branding) return;\r\n        const direct = branding.normalizeSchoolName(userData.schoolName);\r\n        if (userData.logoUrl || userData.schoolLogoUrl) branding.persistSchoolLogo?.(userData.logoUrl || userData.schoolLogoUrl);\r\n        if (direct) { branding.persistSchoolName(direct); return; }\r\n        const adminId = linkedSchoolId(userData) || (userData.role === \"admin\" ? userId : \"\");\r\n        if (!adminId) return;\r\n        let appliedName = false;\r\n        const adminDoc = await getDoc(doc(db, \"users\", adminId));\r\n        if (adminDoc.exists()) {\r\n            const adminData = adminDoc.data();\r\n            const n = branding.normalizeSchoolName(adminData.schoolName);\r\n            if (adminData.logoUrl || adminData.schoolLogoUrl) branding.persistSchoolLogo?.(adminData.logoUrl || adminData.schoolLogoUrl);\r\n            if (n) { branding.persistSchoolName(n); appliedName = true; }\r\n        }\r\n        const brandDoc = await getDoc(doc(db, \"schools\", adminId, \"config\", \"branding\"));\r\n        if (brandDoc.exists()) {\r\n            const brandData = brandDoc.data();\r\n            const n = branding.normalizeSchoolName(brandData.schoolName);\r\n            if (brandData.logoUrl || brandData.schoolLogoUrl) branding.persistSchoolLogo?.(brandData.logoUrl || brandData.schoolLogoUrl);\r\n            if (n && !appliedName) branding.persistSchoolName(n);\r\n        }\r\n    } catch (e) { console.warn(\"Branding sync failed:\", e); }\r\n}\r\n\r\nasync function checkUserRoleAndRedirect(user) {\r\n    try {\r\n        setAuthGate(\"Restoring your dashboard...\");\r\n        const email = String(user.email || \"\").trim().toLowerCase();\r\n        if (email === SUPER_ADMIN_EMAIL) {\r\n            clearStudentSession();\r\n            try {\r\n                await setDoc(doc(db, \"users\", user.uid), {\r\n                    uid: user.uid,\r\n                    name: \"Ansh Bajpai\",\r\n                    email: SUPER_ADMIN_EMAIL,\r\n                    role: \"superAdmin\",\r\n                    superAdmin: true,\r\n                    access: true,\r\n                    updatedAt: new Date()\r\n                }, { merge: true });\r\n            } catch (profileError) {\r\n                console.warn(\"Super admin profile bootstrap failed:\", profileError);\r\n            }\r\n            setAuthGate(\"Opening super admin console...\");\r\n            window.location.href = \"#/admin-signup.html\";\r\n            return;\r\n        }\r\n        const docRef = await getDoc(doc(db, \"users\", user.uid));\r\n        let data = docRef.exists() ? docRef.data() : null;\r\n        if (!data) {\r\n            const recoveredUser = await findSignedInUserRecord(user);\r\n            if (recoveredUser) {\r\n                data = recoveredUser;\r\n            }\r\n        }\r\n        if (!data) {\r\n            const recoveredStudent = await findSignedInStudentRecord(user);\r\n            if (recoveredStudent) {\r\n                const adminData = await getAdminAccessData(user.uid, recoveredStudent);\r\n                const accessReason = accessErrorFor(adminData);\r\n                if (accessReason) {\r\n                    await signOut(auth).catch(() => {});\r\n                    hideAuthGate();\r\n                    showError(accessReason);\r\n                    return;\r\n                }\r\n                syncSchoolName(user.uid, recoveredStudent).catch(() => {});\r\n                saveStudentSession(buildStudentSession(user, recoveredStudent, adminData));\r\n                setAuthGate(\"Opening student dashboard...\");\r\n                window.location.href = \"#/student-dashboard.html\";\r\n                return;\r\n            }\r\n            hideAuthGate(); showError(\"User data not found. Contact admin.\"); return;\r\n        }\r\n        const role = data.role;\r\n        if (data.email && user.email && data.email.toLowerCase() !== user.email.toLowerCase()) {\r\n            hideAuthGate();\r\n            showError(\"Account mismatch detected\"); return;\r\n        }\r\n        clearStudentSession();\r\n        clearTeacherSession();\r\n        const adminData = await getAdminAccessData(user.uid, data);\r\n        const accessReason = accessErrorFor(adminData || data, role === \"admin\" ? \"dashboard\" : \"\");\r\n        if (accessReason) {\r\n            await signOut(auth).catch(() => {});\r\n            hideAuthGate();\r\n            showError(accessReason);\r\n            return;\r\n        }\r\n        syncSchoolName(user.uid, data).catch(() => {});\r\n        if (isNativeSchoolixApp() && role === \"admin\") {\r\n            await signOut(auth).catch(() => {});\r\n            hideAuthGate();\r\n            showError(\"Admin login is only available on the web panel. Please use a student, parent, teacher, librarian, or accountant account in the app.\");\r\n            return;\r\n        }\r\n        if (role === \"teacher\") {\r\n            setAuthGate(\"Opening teacher dashboard...\");\r\n            const teacherSession = buildTeacherSession(user, data, adminData, { loginAs: \"teacher\" });\r\n            saveTeacherSession(teacherSession);\r\n            window.location.href = \"#/teacher-dashboard.html\"; return;\r\n        }\r\n        if (role === \"admin\") { window.location.href = \"#/admin-dashboard.html\"; return; }\r\n        if (role === \"librarian\") { window.location.href = \"#/library-dashboard.html\"; return; }\r\n        if (role === \"accountant\") { window.location.href = \"#/accountant-dashboard.html?v=accountant-dashboard-recovery-20260806\"; return; }\r\n        if (role === \"driver\") {\r\n            setAuthGate(\"Opening driver dashboard...\");\r\n            window.location.href = \"#/driver-dashboard.html\"; return;\r\n        }\r\n        if (role === \"student\") {\r\n            setAuthGate(\"Opening student dashboard...\");\r\n            saveStudentSession(buildStudentSession(user, data, adminData, { loginAs: \"student\" }));\r\n            window.location.href = \"#/student-dashboard.html\"; return;\r\n        }\r\n        hideAuthGate();\r\n        showError(\"Invalid role assigned\");\r\n    } catch (e) { hideAuthGate(); showError(\"Login error. Try again.\"); }\r\n}\r\n\r\nloginForm.addEventListener('submit', async (e) => {\r\n    e.preventDefault();\r\n    const identifier = emailInput.value.trim();\r\n    const password = passwordInput.value.trim();\r\n    if (!identifier || !password) { showError('Please fill all fields'); return; }\r\n    showLoading(true);\r\n\r\n    const looksLikeEmail = identifier.includes(\"@\") || identifier.toLowerCase().includes(\".com\") || identifier.toLowerCase().includes(\".in\");\r\n\r\n    try {\r\n        let directAuthError = null;\r\n        if (looksLikeEmail) {\r\n            try {\r\n                const authId = identifier.toLowerCase();\r\n                const cred = await signInWithEmailAndPassword(auth, authId, password);\r\n                await checkUserRoleAndRedirect(cred.user);\r\n                return;\r\n            } catch (error) {\r\n                directAuthError = error;\r\n            }\r\n        }\r\n\r\n        let studentLogin = { success: false, reason: \"\" };\r\n        try {\r\n            studentLogin = await loginStudent(identifier, password);\r\n            if (studentLogin.success) return;\r\n        } catch (studentAuthError) {\r\n            studentLogin.reason = studentAuthError.code === \"auth/wrong-password\" || studentAuthError.code === \"auth/invalid-credential\"\r\n                ? \"Wrong student password\"\r\n                : studentAuthError.code === \"auth/user-not-found\"\r\n                    ? \"No login account found for this student. Contact admin.\"\r\n                    : studentAuthError.message;\r\n        }\r\n\r\n        const authError = directAuthError || new Error(studentLogin.reason || \"Login failed\");\r\n        showError(studentLogin.reason || userFacingAuthError(authError));\r\n    } catch (authError) {\r\n        showError(userFacingAuthError(authError));\r\n    } finally { showLoading(false); }\r\n});\r\n\r\nasync function finishGoogleLogin(user) {\r\n    if (!user) return false;\r\n    authRedirectInProgress = true;\r\n    try {\r\n        await checkUserRoleAndRedirect(user);\r\n    } finally {\r\n        setTimeout(() => { authRedirectInProgress = false; }, 1500);\r\n    }\r\n    return true;\r\n}\r\n\r\n\r\nasync function handleGoogleRedirectResult() {\r\n    try {\r\n        const result = await getRedirectResult(auth);\r\n        if (result?.user) {\r\n            setAuthGate(\"Opening your dashboard...\");\r\n            await finishGoogleLogin(result.user);\r\n        }\r\n    } catch (error) {\r\n        hideAuthGate();\r\n        showError(userFacingAuthError(error, \"Google login failed. Please try again.\"));\r\n    }\r\n}\r\n\r\nwindow.loginWithGoogle = async () => {\r\n    showLoading(true);\r\n    try {\r\n        if (isNativeSchoolixApp() && window.SchoolixNativeAuth?.signInWithGoogle) {\r\n            const result = await signInWithNativeGoogle();\r\n            await finishGoogleLogin(result.user);\r\n            return;\r\n        }\r\n        const result = await signInWithPopup(auth, googleProvider);\r\n        await finishGoogleLogin(result.user);\r\n    } catch (e) {\r\n        const code = String(e?.code || \"\");\r\n        if (code.includes(\"popup\") || code.includes(\"cancelled\") || code.includes(\"operation-not-supported\")) {\r\n            try {\r\n                await signInWithRedirect(auth, googleProvider);\r\n                return;\r\n            } catch (redirectError) {\r\n                showError(userFacingAuthError(redirectError, \"Google login failed. Please try again.\"));\r\n            }\r\n        } else {\r\n            showError(userFacingAuthError(e, \"Google login failed. Please try again.\"));\r\n        }\r\n    } finally { showLoading(false); }\r\n};\r\n\r\nwindow.resetPassword = async () => {\r\n    const identifier = emailInput.value.trim();\r\n    if (!identifier) { showError('Please enter your email or Student ID first'); return; }\r\n    showLoading(true);\r\n    try {\r\n        let emailToReset = identifier;\r\n        if (!identifier.includes(\"@\")) {\r\n            const student = await findStudentRecord(identifier, { parent: true });\r\n            if (!student) { showError('Student record not found'); return; }\r\n            emailToReset = String(student.authEmail || student.email || \"\").trim();\r\n            if (!emailToReset || emailToReset.endsWith(\"@schoolix.student\")) {\r\n                showError('No registered email found for this student. Contact admin.');\r\n                return;\r\n            }\r\n        }\r\n        await requestPasswordResetEmail(emailToReset);\r\n        showError('Password reset email sent to your registered address');\r\n    } catch (e) {\r\n        showError(userFacingAuthError(e, \"Password reset email failed. Contact admin.\"));\r\n    } finally { showLoading(false); }\r\n};\r\n\r\nhandleGoogleRedirectResult();\r\n\r\nonAuthStateChanged(auth, async (user) => {\r\n    if (authRedirectInProgress) return;\r\n    if (user) { await checkUserRoleAndRedirect(user); return; }\r\n    const savedStudentSession = loadStudentSession();\r\n    if (savedStudentSession) {\r\n        clearStudentSession();\r\n        showError(\"Your saved session expired. Please sign in again.\");\r\n    }\r\n    hideAuthGate();\r\n});\r\n</script>\r\n  <script src=\"schoolix-polish.js\" defer></script>\r\n","styles":[{"tag":"style","attributes":{"id":"sxCriticalLoaderStyle"},"text":"\nhtml.sx-page-loading,\nhtml.sx-page-loading body {\n  min-height: 100%;\n  background: #f8fafc !important;\n}\nhtml.sx-page-loading body::before,\nhtml.sx-page-loading body::after {\n  visibility: hidden !important;\n}\nhtml.sx-page-loading body > :not(#sxPageLoader):not(script):not(style) {\n  visibility: hidden !important;\n}\n.sx-page-loader {\n  position: fixed;\n  inset: 0;\n  z-index: 2147482500;\n  display: flex;\n  align-items: stretch;\n  justify-content: stretch;\n  background: #f8fafc;\n  transition: opacity 0.25s cubic-bezier(0.4, 0, 0.2, 1), visibility 0.25s ease;\n  overflow: hidden;\n}\n.sx-page-loader.is-hidden {\n  opacity: 0;\n  visibility: hidden;\n  pointer-events: none;\n}\n.sx-page-loader .dots-container {\n  position: fixed;\n  inset: 0;\n  display: block;\n  width: 100vw;\n  height: 100vh;\n  padding: 0;\n  margin: 0;\n  overflow: hidden;\n  background: #f8fafc;\n}\n.sx-page-loader .dots-container::before,\n.sx-page-loader .dots-container::after,\n.sx-page-loader .dot {\n  display: none !important;\n}\n"},{"tag":"link","attributes":{"rel":"preload","href":"/schoolix-erp.css","as":"style","onload":"this.onload=null;this.rel="},"text":""},{"tag":"link","attributes":{"rel":"preload","href":"schoolix-polish.css","as":"style","onload":"this.onload=null;this.rel="},"text":""},{"tag":"link","attributes":{"rel":"stylesheet","href":"/schoolix-erp.css"},"text":""},{"tag":"link","attributes":{"rel":"stylesheet","href":"schoolix-polish.css"},"text":""}],"scripts":[{"attributes":{"id":"sxCriticalLoaderScript"},"text":"\r\n(function () {\r\n  var root = document.documentElement;\r\n  root.classList.add(\"sx-page-loading\");\r\n  window.SchoolixPageLoaderEarly = window.SchoolixPageLoaderEarly || { startedAt: Date.now() };\r\n\r\n  function markEarlyReady(reason) {\r\n    window.SchoolixPageLoaderEarly.ready = true;\r\n    window.SchoolixPageLoaderEarly.reason = reason || \"dom-ready\";\r\n    try {\r\n      window.dispatchEvent(new CustomEvent(\"schoolix:critical-load-ready\", { detail: window.SchoolixPageLoaderEarly }));\r\n    } catch (_) {}\r\n  }\r\n\r\n  function afterFirstPaint(reason) {\r\n    requestAnimationFrame(function () {\r\n      requestAnimationFrame(function () { markEarlyReady(reason); });\r\n    });\r\n  }\r\n\r\n  function emergencyHide() {\r\n    if (window.SchoolixPageLoader || !root.classList.contains(\"sx-page-loading\")) return;\r\n    root.classList.remove(\"sx-page-loading\");\r\n    root.classList.add(\"sx-page-loaded\");\r\n    var loader = document.getElementById(\"sxPageLoader\");\r\n    if (!loader) return;\r\n    loader.classList.add(\"is-hidden\");\r\n    setTimeout(function () { loader.remove(); }, 260);\r\n  }\r\n\r\n  if (document.readyState === \"loading\") {\r\n    document.addEventListener(\"DOMContentLoaded\", function () { afterFirstPaint(\"dom-ready\"); }, { once: true });\r\n  } else {\r\n    afterFirstPaint(document.readyState === \"complete\" ? \"document-complete\" : \"dom-ready\");\r\n  }\r\n  window.addEventListener(\"load\", function () { markEarlyReady(\"window-load\"); }, { once: true });\r\n  setTimeout(emergencyHide, 1400);\r\n}());\r\n"},{"attributes":{"src":"school-branding.js"},"text":""},{"attributes":{"src":"/schoolix-app.js?v=navbar-20260721"},"text":""},{"attributes":{"type":"module"},"text":"\r\nimport { initializeApp } from \"./firebase-compat.js\";\r\nimport {\r\n    getAuth,\r\n    signInWithEmailAndPassword,\r\n    signInWithPopup,\r\n    signInWithRedirect,\r\n    getRedirectResult,\r\n    signInWithCredential,\r\n    GoogleAuthProvider,\r\n    onAuthStateChanged,\r\n    signOut\r\n} from \"./firebase-compat.js\";\r\nimport {\r\n    getFirestore,\r\n    doc,\r\n    getDoc,\r\n    getDocs,\r\n    collection,\r\n    query,\r\n    where,\r\n    limit,\r\n    setDoc\r\n} from \"./firebase-compat.js\";\r\n\r\nconst firebaseConfig = {\r\n    apiKey: \"AIzaSyAomGwef93HFT9Xyx7SVW95FPw_IcIAICE\",\r\n    authDomain: \"schoolix-48107.firebaseapp.com\",\r\n    projectId: \"schoolix-48107\"\r\n};\r\n\r\nconst app = initializeApp(firebaseConfig);\r\nconst auth = getAuth(app);\r\nconst db = getFirestore(app);\r\nconst googleProvider = new GoogleAuthProvider();\r\ngoogleProvider.setCustomParameters({ prompt: \"select_account\" });\r\n\r\nconst SUPABASE_URL = \"https://ezkmeedcqetztkeppxil.supabase.co\";\r\nconst SUPABASE_ANON_KEY = \"eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImV6a21lZWRjcWV0enRrZXBweGlsIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzgxMjk5NjAsImV4cCI6MjA5MzcwNTk2MH0.1davJ_NYkFhHToUtcFBR0kA6dk0-cOkaIbK2SCObkQg\";\r\nconst PASSWORD_RESET_FUNCTION_URL = `${SUPABASE_URL}/functions/v1/send-password-reset-email`;\r\n\r\nconst loginForm = document.getElementById('loginForm');\r\nconst emailInput = document.getElementById('email');\r\nconst passwordInput = document.getElementById('password');\r\nconst loadingEl = document.getElementById('loading');\r\nconst errorEl = document.getElementById('errorMsg');\r\nconst errorText = document.getElementById('errorText');\r\nconst togglePasswordBtn = document.getElementById('togglePassword');\r\nconst eyeIcon = document.getElementById('eyeIcon');\r\nconst downloadAndroidApp = document.getElementById('downloadAndroidApp');\r\nconst downloadAndroidLabel = document.getElementById('downloadAndroidLabel');\r\nconst downloadAndroidMeta = document.getElementById('downloadAndroidMeta');\r\nconst authGate = document.getElementById('authGate');\r\nconst authGateText = document.getElementById('authGateText');\r\nlet authRedirectInProgress = false;\r\nlet nativeGoogleResolve = null;\r\nlet nativeGoogleReject = null;\r\n\r\nconst STUDENT_SESSION_KEY = \"schoolixStudentSession\";\r\nconst TEACHER_SESSION_KEY = \"schoolixTeacherSession\";\r\nconst SUPER_ADMIN_EMAIL = \"anshbajpai4@gmail.com\";\r\n\r\nfunction loadStudentSession() {\r\n    try { return JSON.parse(localStorage.getItem(STUDENT_SESSION_KEY)); } catch { return null; }\r\n}\r\nfunction saveStudentSession(data) {\r\n    localStorage.setItem(STUDENT_SESSION_KEY, JSON.stringify(data));\r\n}\r\nfunction clearStudentSession() {\r\n    localStorage.removeItem(STUDENT_SESSION_KEY);\r\n}\r\n\r\nfunction loadTeacherSession() {\r\n    try { return JSON.parse(localStorage.getItem(TEACHER_SESSION_KEY)); } catch { return null; }\r\n}\r\nfunction saveTeacherSession(session) {\r\n    if (!session) return;\r\n    try {\r\n        const json = JSON.stringify(session);\r\n        localStorage.setItem(TEACHER_SESSION_KEY, json);\r\n        localStorage.setItem(\"schoolixLastTeacherProfile\", json);\r\n        if (session.uid) {\r\n            localStorage.setItem(`schoolixTeacherProfile_${session.uid}`, json);\r\n        }\r\n        if (session.email) {\r\n            localStorage.setItem(`schoolixTeacherProfileEmail_${String(session.email).trim().toLowerCase()}`, json);\r\n        }\r\n        const schoolId = session.schoolId || session.adminId || \"\";\r\n        if (schoolId) {\r\n            localStorage.setItem(\"teacherSchoolId\", schoolId);\r\n            if (session.schoolName) {\r\n                localStorage.setItem(`schoolixSchoolName_${schoolId}`, session.schoolName);\r\n            }\r\n        }\r\n        if (session.schoolName) {\r\n            window.SchoolBranding?.persistSchoolName?.(session.schoolName);\r\n            try { localStorage.setItem(\"schoolix.schoolName\", session.schoolName); } catch {}\r\n        }\r\n        if (session.logoUrl) {\r\n            window.SchoolBranding?.persistSchoolLogo?.(session.logoUrl);\r\n        }\r\n        if (session.section) {\r\n            localStorage.setItem(\"teacherSection\", session.section);\r\n        }\r\n    } catch (e) {\r\n        console.warn(\"Unable to save teacher session:\", e);\r\n    }\r\n}\r\nfunction clearTeacherSession() {\r\n    try {\r\n        localStorage.removeItem(TEACHER_SESSION_KEY);\r\n        localStorage.removeItem(\"schoolixLastTeacherProfile\");\r\n    } catch {}\r\n}\r\n\r\nfunction userFacingAuthError(error, fallback = \"Login failed. Please try again.\") {\r\n    const code = String(error?.code || \"\").toLowerCase();\r\n    const messages = {\r\n        \"auth/user-not-found\": \"The email or password is incorrect.\",\r\n        \"auth/wrong-password\": \"The email or password is incorrect.\",\r\n        \"auth/invalid-credential\": \"The email or password is incorrect.\",\r\n        \"auth/invalid-credentials\": \"The email or password is incorrect.\",\r\n        \"auth/invalid-email\": \"Enter a valid email address.\",\r\n        \"auth/too-many-requests\": \"Too many attempts. Please wait a moment and try again.\",\r\n        \"network-request-failed\": \"Network connection failed. Check your internet and try again.\",\r\n        \"deadline-exceeded\": \"The request took too long. Check your connection and try again.\",\r\n        \"unavailable\": \"Schoolix is temporarily unavailable. Please try again shortly.\"\r\n    };\r\n    return messages[code] || window.SchoolixErrors?.message?.(error, fallback) || fallback;\r\n}\r\n\r\nasync function requestPasswordResetEmail(email) {\r\n    const controller = new AbortController();\r\n    const timeoutId = setTimeout(() => controller.abort(), 20000);\r\n    try {\r\n        const response = await fetch(PASSWORD_RESET_FUNCTION_URL, {\r\n            method: \"POST\",\r\n            headers: {\r\n                \"Content-Type\": \"application/json\",\r\n                \"apikey\": SUPABASE_ANON_KEY,\r\n                \"Authorization\": `Bearer ${SUPABASE_ANON_KEY}`\r\n            },\r\n            body: JSON.stringify({\r\n                email,\r\n                schoolName: window.SchoolBranding?.getSchoolName() || \"Schoolix\"\r\n            }),\r\n            signal: controller.signal\r\n        });\r\n        if (!response.ok) {\r\n            const error = new Error(\"Password reset email could not be sent.\");\r\n            error.code = response.status === 429 ? \"resource-exhausted\" : response.status >= 500 ? \"unavailable\" : \"unknown\";\r\n            throw error;\r\n        }\r\n    } catch (error) {\r\n        if (error.name === \"AbortError\") {\r\n            const timeoutError = new Error(\"Password reset request timed out.\");\r\n            timeoutError.code = \"deadline-exceeded\";\r\n            throw timeoutError;\r\n        }\r\n        throw error;\r\n    } finally {\r\n        clearTimeout(timeoutId);\r\n    }\r\n}\r\n\r\nfunction linkedSchoolId(profile = {}, adminData = null) {\r\n    return String(\r\n        profile.schoolId || profile.schoolID || profile.schoolUid || profile.schoolUID || profile.schoolDocId || profile.schoolDocID ||\r\n        profile.adminId || profile.adminID || profile.adminUid || profile.adminUID || profile.adminDocId || profile.adminDocID ||\r\n        adminData?.schoolId || adminData?.schoolID || adminData?.schoolUid || adminData?.schoolUID ||\r\n        adminData?.adminId || adminData?.adminID || adminData?.adminUid || adminData?.adminUID ||\r\n        adminData?.schoolDocId || adminData?.schoolDocID || adminData?.adminDocId || adminData?.adminID || adminData?.id || \"\"\r\n    ).trim();\r\n}\r\n\r\nfunction buildStudentSession(user, student = {}, adminData = null, extra = {}) {\r\n    const schoolId = linkedSchoolId(student, adminData);\r\n    const schoolName = student.schoolName || adminData?.schoolName || window.SchoolBranding?.getSchoolName?.() || \"\";\r\n    return {\r\n        uid: user.uid,\r\n        authUid: user.supabaseUid || user.uid,\r\n        supabaseAuthUid: user.supabaseUid || \"\",\r\n        studentId: student.studentId || student.id || user.uid,\r\n        studentDocId: student.studentDocId || student.id || \"\",\r\n        name: student.name || student.fullName || student.studentName || \"\",\r\n        class: student.class || \"\",\r\n        section: student.section || \"\",\r\n        rollNo: student.rollNo || student.roll || \"\",\r\n        email: student.email || student.authEmail || user.email || \"\",\r\n        schoolId,\r\n        schoolName,\r\n        role: \"student\",\r\n        loginAt: new Date().toISOString(),\r\n        ...extra\r\n    };\r\n}\r\n\r\nfunction buildTeacherSession(user, teacher = {}, adminData = null, extra = {}) {\r\n    const schoolId = linkedSchoolId(teacher, adminData);\r\n    const schoolName = teacher.schoolName || adminData?.schoolName || adminData?.instituteName || window.SchoolBranding?.getSchoolName?.() || \"\";\r\n    const logoUrl = teacher.logoUrl || teacher.schoolLogoUrl || adminData?.logoUrl || adminData?.schoolLogoUrl || \"\";\r\n    const photoUrl = teacher.photoUrl || teacher.imageUrl || teacher.profilePhotoUrl || teacher.avatarUrl || \"\";\r\n    const name = teacher.name || teacher.fullName || teacher.teacherName || teacher.displayName || user.displayName || \"\";\r\n    return {\r\n        uid: user.uid,\r\n        authUid: user.supabaseUid || user.uid,\r\n        supabaseAuthUid: user.supabaseUid || \"\",\r\n        docId: teacher.id || user.uid,\r\n        teacherId: teacher.teacherId || teacher.staffId || teacher.id || \"\",\r\n        name,\r\n        displayName: name,\r\n        email: teacher.email || teacher.authEmail || user.email || \"\",\r\n        class: teacher.class || \"\",\r\n        section: teacher.section || \"\",\r\n        assignedClasses: teacher.assignedClasses || [],\r\n        schoolId,\r\n        adminId: schoolId,\r\n        schoolName,\r\n        logoUrl,\r\n        photoUrl,\r\n        role: \"teacher\",\r\n        loginAt: new Date().toISOString(),\r\n        ...extra\r\n    };\r\n}\r\n\r\nconst FEATURE_LABELS = {\r\n    dashboard: \"Dashboard\",\r\n    teachers: \"Teachers\",\r\n    students: \"Students\",\r\n    attendance: \"Attendance\",\r\n    payroll: \"Payroll\",\r\n    reports: \"Reports\",\r\n    announcements: \"Announcements\",\r\n    settings: \"Settings\"\r\n};\r\n\r\nasync function hydrateAndroidDownloadLink() {\r\n    if (!downloadAndroidApp) return;\r\n    const fallbackUrl = \"/dist/Schoolix-download\";\r\n    try {\r\n        const response = await fetch(`/version.json?t=${Date.now()}`, { cache: \"no-store\" });\r\n        if (!response.ok) throw new Error(\"version.json unavailable\");\r\n        const data = await response.json();\r\n        const apkUrl = String(data.apkUrl || fallbackUrl).trim();\r\n        downloadAndroidApp.href = apkUrl || fallbackUrl;\r\n        if (downloadAndroidLabel) downloadAndroidLabel.textContent = \"Download Latest Android App\";\r\n        if (downloadAndroidMeta) {\r\n            const versionName = data.versionName ? `v${data.versionName}` : \"Latest version\";\r\n            const versionCode = data.versionCode ? ` build ${data.versionCode}` : \"\";\r\n            downloadAndroidMeta.textContent = `${versionName}${versionCode}`;\r\n        }\r\n    } catch (error) {\r\n        console.warn(\"Unable to load APK metadata:\", error);\r\n        downloadAndroidApp.href = fallbackUrl;\r\n        if (downloadAndroidMeta) downloadAndroidMeta.textContent = \"Latest APK\";\r\n    }\r\n}\r\n\r\nfunction scheduleAndroidDownloadHydration() {\r\n    const run = () => {\r\n        if (\"requestIdleCallback\" in window) window.requestIdleCallback(() => hydrateAndroidDownloadLink(), { timeout: 3000 });\r\n        else setTimeout(() => hydrateAndroidDownloadLink(), 1500);\r\n    };\r\n    if (document.readyState === \"complete\") run();\r\n    else window.addEventListener(\"load\", run, { once: true });\r\n}\r\n\r\nscheduleAndroidDownloadHydration();\r\n\r\nfunction accessErrorFor(adminData, featureKey = \"\") {\r\n    if (!adminData || adminData.access === false) {\r\n        return \"Your school's platform access has been disabled by the Super Admin. Please contact support.\";\r\n    }\r\n    if (featureKey && (adminData.features || {})[featureKey] === false) {\r\n        return `${FEATURE_LABELS[featureKey] || \"This\"} access has been disabled for your school by the Super Admin.`;\r\n    }\r\n    return \"\";\r\n}\r\n\r\nasync function getAdminAccessData(userId, userData) {\r\n    if (!userData) return null;\r\n    if ((userData.role || \"\").toLowerCase() === \"admin\") return { id: userId, ...userData };\r\n    const adminId = linkedSchoolId(userData);\r\n    if (!adminId) return null;\r\n    try {\r\n        const adminSnap = await getDoc(doc(db, \"users\", adminId));\r\n        return adminSnap.exists() ? { id: adminSnap.id, ...adminSnap.data() } : null;\r\n    } catch (error) {\r\n        console.warn(\"Unable to load admin access profile\", error);\r\n        return null;\r\n    }\r\n}\r\n\r\nconst EYE_OPEN = `<path d=\"M12 5c-5.5 0-10 4.5-11 7 1 2.5 5.5 7 11 7s10-4.5 11-7c-1-2.5-5.5-7-11-7Zm0 11.5A4.5 4.5 0 1 1 12 7a4.5 4.5 0 0 1 0 9.5Zm0-2A2.5 2.5 0 1 0 12 9a2.5 2.5 0 0 0 0 5Z\"/>`;\r\nconst EYE_CLOSED = `<path d=\"M2.1 3.51 3.51 2.1l18.38 18.38-1.41 1.41-3.3-3.3A10.96 10.96 0 0 1 12 21C6.5 21 2 16.5 1 14c.52-1.31 1.63-2.97 3.22-4.49l-.21-.21A.99.99 0 0 1 2.1 3.51ZM12 7c2.76 0 5 2.24 5 5 0 .62-.11 1.21-.32 1.76l-1.6-1.6A2.97 2.97 0 0 0 12 9c-.7 0-1.34.24-1.85.64L8.79 8.28A4.97 4.97 0 0 1 12 7Zm0 10c-2.76 0-5-2.24-5-5 0-.74.16-1.45.43-2.08L5.37 8.86C4 10.12 3.1 11.42 2.78 12c1 2.09 4.59 6 9.22 6 1.11 0 2.17-.18 3.14-.5l-1.69-1.69c-.45.12-.93.19-1.45.19Zm5.63-2.69 1.48 1.48C20.48 14.93 21.48 13.46 21.9 12c-1-2.5-5.5-7-9.9-7-1.25 0-2.46.23-3.56.65l1.56 1.56c.62-.14 1.28-.21 1.98-.21 2.76 0 5 2.24 5 5 0 .47-.07.92-.2 1.31Z\"/>`;\r\n\r\ntogglePasswordBtn.addEventListener('click', () => {\r\n    const isHidden = passwordInput.type === \"password\";\r\n    passwordInput.type = isHidden ? \"text\" : \"password\";\r\n    eyeIcon.innerHTML = isHidden ? EYE_CLOSED : EYE_OPEN;\r\n    togglePasswordBtn.setAttribute(\"aria-label\", isHidden ? \"Hide password\" : \"Show password\");\r\n    togglePasswordBtn.setAttribute(\"aria-pressed\", String(isHidden));\r\n});\r\n\r\nfunction showError(message) {\r\n    errorText.textContent = message;\r\n    errorEl.classList.add('visible');\r\n    setTimeout(() => errorEl.classList.remove('visible'), 5500);\r\n}\r\n\r\nconst accessError = new URLSearchParams(window.location.search).get(\"access_error\");\r\nif (accessError) {\r\n    showError(accessError);\r\n    history.replaceState({}, document.title, window.location.pathname);\r\n}\r\n\r\nfunction showLoading(show) {\r\n    loadingEl.classList.toggle('visible', show);\r\n    loginForm.style.opacity = show ? '0.65' : '1';\r\n    loginForm.style.pointerEvents = show ? 'none' : '';\r\n}\r\n\r\nfunction setAuthGate(message) {\r\n    if (authGateText && message) authGateText.textContent = message;\r\n    document.body.classList.add(\"auth-checking\");\r\n    authGate?.classList.remove(\"hidden\");\r\n}\r\n\r\nfunction hideAuthGate() {\r\n    document.body.classList.remove(\"auth-checking\");\r\n    authGate?.classList.add(\"hidden\");\r\n}\r\n\r\nfunction isNativeSchoolixApp() {\r\n    try {\r\n        if (window.Capacitor?.isNativePlatform?.()) return true;\r\n        return location.protocol === \"capacitor:\";\r\n    } catch {\r\n        return false;\r\n    }\r\n}\r\n\r\nfunction signInWithNativeGoogle() {\r\n    return new Promise((resolve, reject) => {\r\n        if (!window.SchoolixNativeAuth?.signInWithGoogle) {\r\n            reject(new Error(\"Native Google login is not available\"));\r\n            return;\r\n        }\r\n        nativeGoogleResolve = resolve;\r\n        nativeGoogleReject = reject;\r\n        window.SchoolixNativeAuth.signInWithGoogle();\r\n    });\r\n}\r\n\r\nwindow.SchoolixNativeGoogleAuth = {\r\n    async receiveIdToken(idToken) {\r\n        try {\r\n            const token = String(idToken || \"\").trim();\r\n            if (!token) throw new Error(\"Google login token was not received\");\r\n            const credential = GoogleAuthProvider.credential(token);\r\n            const result = await signInWithCredential(auth, credential);\r\n            nativeGoogleResolve?.(result);\r\n        } catch (error) {\r\n            nativeGoogleReject?.(error);\r\n        } finally {\r\n            nativeGoogleResolve = null;\r\n            nativeGoogleReject = null;\r\n        }\r\n    },\r\n    receiveError(message) {\r\n        nativeGoogleReject?.(new Error(message || \"Google login failed\"));\r\n        nativeGoogleResolve = null;\r\n        nativeGoogleReject = null;\r\n    }\r\n};\r\n\r\nfunction isParentIdentifier(identifier, student) {\r\n    const lowered = String(identifier || \"\").trim().toLowerCase();\r\n    if (!lowered || !lowered.includes(\"@\")) return false;\r\n    if (String(student.email || \"\").trim().toLowerCase() === lowered) return false;\r\n    if (String(student.authEmail || \"\").trim().toLowerCase() === lowered) return false;\r\n    return [student.parentEmail, student.fatherEmail, student.motherEmail, student.guardianEmail]\r\n        .some(email => String(email || \"\").trim().toLowerCase() === lowered);\r\n}\r\n\r\nfunction uniqueLookupValues(values = []) {\r\n    const seen = new Set();\r\n    return values\r\n        .map(value => typeof value === \"string\" ? value.trim() : value)\r\n        .filter(value => value !== \"\" && value !== null && value !== undefined)\r\n        .filter(value => {\r\n            const key = `${typeof value}:${String(value)}`;\r\n            if (seen.has(key)) return false;\r\n            seen.add(key);\r\n            return true;\r\n        });\r\n}\r\n\r\nasync function findStudentRecord(identifier, options = {}) {\r\n    const normalized = identifier.trim();\r\n    if (!normalized) return null;\r\n    const lowered = normalized.toLowerCase();\r\n    const uppered = normalized.toUpperCase();\r\n    const idValues = uniqueLookupValues([\r\n        normalized,\r\n        lowered,\r\n        uppered,\r\n        /^\\d+$/.test(normalized) ? Number(normalized) : null\r\n    ]);\r\n\r\n    for (const docId of uniqueLookupValues([normalized, lowered, uppered])) {\r\n        try {\r\n            const byIdDoc = await getDoc(doc(db, \"users\", docId));\r\n            if (byIdDoc.exists() && (byIdDoc.data().role || \"\").toLowerCase() === \"student\") {\r\n                return { id: byIdDoc.id, ...byIdDoc.data() };\r\n            }\r\n        } catch (error) {\r\n            if (error?.code !== \"permission-denied\") console.warn(\"Student direct lookup failed:\", error);\r\n        }\r\n    }\r\n\r\n    const lookups = [\r\n        [\"studentId\", idValues],\r\n        [\"email\", uniqueLookupValues([lowered, normalized])],\r\n        [\"authEmail\", uniqueLookupValues([lowered, normalized])]\r\n    ];\r\n    if (options.parent) {\r\n        const emailValues = uniqueLookupValues([lowered, normalized]);\r\n        lookups.push(\r\n            [\"parentEmail\", emailValues],\r\n            [\"fatherEmail\", emailValues],\r\n            [\"motherEmail\", emailValues],\r\n            [\"guardianEmail\", emailValues]\r\n        );\r\n    }\r\n    for (const [field, values] of lookups) {\r\n        for (const value of values) {\r\n            try {\r\n                const snap = await getDocs(query(\r\n                    collection(db, \"users\"),\r\n                    where(\"role\", \"==\", \"student\"),\r\n                    where(field, \"==\", value),\r\n                    limit(1)\r\n                ));\r\n                if (!snap.empty) return { id: snap.docs[0].id, ...snap.docs[0].data() };\r\n            } catch (error) {\r\n                if (error?.code !== \"permission-denied\") console.warn(`Student ${field} lookup failed:`, error);\r\n            }\r\n        }\r\n    }\r\n    return null;\r\n}\r\n\r\nasync function loginStudent(identifier, password, options = {}) {\r\n    const student = await findStudentRecord(identifier, { parent: true });\r\n    if (!student) return { success: false, reason: \"Student or parent record not found.\" };\r\n    const authEmail = String(student.authEmail || student.email || \"\").trim().toLowerCase();\r\n    if (!authEmail || authEmail.endsWith(\"@schoolix.student\")) {\r\n        return { success: false, reason: \"Registered email is missing for this student. Contact admin to update the student login email.\" };\r\n    }\r\n    const cred = await signInWithEmailAndPassword(auth, authEmail, password);\r\n    const expectedAuthUid = String(student.authUid || \"\").trim();\r\n    const signedInIds = [cred.user.uid, cred.user.supabaseUid].map(value => String(value || \"\").trim()).filter(Boolean);\r\n    const signedInEmail = String(cred.user.email || \"\").trim().toLowerCase();\r\n    const studentEmails = [student.authEmail, student.email]\r\n        .map(value => String(value || \"\").trim().toLowerCase())\r\n        .filter(Boolean);\r\n    if (expectedAuthUid && !signedInIds.includes(expectedAuthUid) && !studentEmails.includes(signedInEmail)) {\r\n        await signOut(auth).catch(() => {});\r\n        return { success: false, reason: \"Student login record is linked to a different account. Contact admin to refresh this student's login.\" };\r\n    }\r\n    const adminData = await getAdminAccessData(cred.user.uid, student);\r\n    const accessReason = accessErrorFor(adminData);\r\n    if (accessReason) {\r\n        await signOut(auth).catch(() => {});\r\n        return { success: false, reason: accessReason };\r\n    }\r\n    if (isParentIdentifier(identifier, student)) {\r\n        saveStudentSession(buildStudentSession(cred.user, student, adminData, {\r\n            loginAs: \"parent\",\r\n            parentEmail: identifier.toLowerCase()\r\n        }));\r\n        window.location.href = \"#/student-dashboard.html\";\r\n        return { success: true };\r\n    }\r\n    saveStudentSession(buildStudentSession(cred.user, student, adminData));\r\n    setAuthGate(\"Opening student dashboard...\");\r\n    window.location.href = \"#/student-dashboard.html\";\r\n    return { success: true };\r\n}\r\n\r\nasync function findSignedInStudentRecord(user) {\r\n    if (!user) return null;\r\n    const uid = String(user.uid || \"\").trim();\r\n    const email = String(user.email || \"\").trim().toLowerCase();\r\n    if (uid) {\r\n        try {\r\n            const snap = await getDocs(query(\r\n                collection(db, \"users\"),\r\n                where(\"role\", \"==\", \"student\"),\r\n                where(\"authUid\", \"==\", uid),\r\n                limit(1)\r\n            ));\r\n            if (!snap.empty) return { id: snap.docs[0].id, ...snap.docs[0].data() };\r\n        } catch (error) {\r\n            if (error?.code !== \"permission-denied\") console.warn(\"Student auth UID lookup failed:\", error);\r\n        }\r\n    }\r\n    return email ? await findStudentRecord(email, { parent: true }) : null;\r\n}\r\n\r\nasync function findSignedInUserRecord(user) {\r\n    if (!user) return null;\r\n    const uid = String(user.uid || \"\").trim();\r\n    const email = String(user.email || \"\").trim().toLowerCase();\r\n    const lookups = [];\r\n    if (uid) lookups.push([\"authUid\", uid], [\"uid\", uid]);\r\n    if (email) lookups.push([\"email\", email], [\"authEmail\", email]);\r\n    for (const [field, value] of lookups) {\r\n        try {\r\n            const snap = await getDocs(query(collection(db, \"users\"), where(field, \"==\", value), limit(1)));\r\n            if (!snap.empty) return { id: snap.docs[0].id, ...snap.docs[0].data() };\r\n        } catch (error) {\r\n            if (error?.code !== \"permission-denied\") console.warn(`Profile ${field} recovery failed:`, error);\r\n        }\r\n    }\r\n    return null;\r\n}\r\n\r\nasync function syncSchoolName(userId, userData) {\r\n    try {\r\n        const branding = window.SchoolBranding;\r\n        if (!branding) return;\r\n        const direct = branding.normalizeSchoolName(userData.schoolName);\r\n        if (userData.logoUrl || userData.schoolLogoUrl) branding.persistSchoolLogo?.(userData.logoUrl || userData.schoolLogoUrl);\r\n        if (direct) { branding.persistSchoolName(direct); return; }\r\n        const adminId = linkedSchoolId(userData) || (userData.role === \"admin\" ? userId : \"\");\r\n        if (!adminId) return;\r\n        let appliedName = false;\r\n        const adminDoc = await getDoc(doc(db, \"users\", adminId));\r\n        if (adminDoc.exists()) {\r\n            const adminData = adminDoc.data();\r\n            const n = branding.normalizeSchoolName(adminData.schoolName);\r\n            if (adminData.logoUrl || adminData.schoolLogoUrl) branding.persistSchoolLogo?.(adminData.logoUrl || adminData.schoolLogoUrl);\r\n            if (n) { branding.persistSchoolName(n); appliedName = true; }\r\n        }\r\n        const brandDoc = await getDoc(doc(db, \"schools\", adminId, \"config\", \"branding\"));\r\n        if (brandDoc.exists()) {\r\n            const brandData = brandDoc.data();\r\n            const n = branding.normalizeSchoolName(brandData.schoolName);\r\n            if (brandData.logoUrl || brandData.schoolLogoUrl) branding.persistSchoolLogo?.(brandData.logoUrl || brandData.schoolLogoUrl);\r\n            if (n && !appliedName) branding.persistSchoolName(n);\r\n        }\r\n    } catch (e) { console.warn(\"Branding sync failed:\", e); }\r\n}\r\n\r\nasync function checkUserRoleAndRedirect(user) {\r\n    try {\r\n        setAuthGate(\"Restoring your dashboard...\");\r\n        const email = String(user.email || \"\").trim().toLowerCase();\r\n        if (email === SUPER_ADMIN_EMAIL) {\r\n            clearStudentSession();\r\n            try {\r\n                await setDoc(doc(db, \"users\", user.uid), {\r\n                    uid: user.uid,\r\n                    name: \"Ansh Bajpai\",\r\n                    email: SUPER_ADMIN_EMAIL,\r\n                    role: \"superAdmin\",\r\n                    superAdmin: true,\r\n                    access: true,\r\n                    updatedAt: new Date()\r\n                }, { merge: true });\r\n            } catch (profileError) {\r\n                console.warn(\"Super admin profile bootstrap failed:\", profileError);\r\n            }\r\n            setAuthGate(\"Opening super admin console...\");\r\n            window.location.href = \"#/admin-signup.html\";\r\n            return;\r\n        }\r\n        const docRef = await getDoc(doc(db, \"users\", user.uid));\r\n        let data = docRef.exists() ? docRef.data() : null;\r\n        if (!data) {\r\n            const recoveredUser = await findSignedInUserRecord(user);\r\n            if (recoveredUser) {\r\n                data = recoveredUser;\r\n            }\r\n        }\r\n        if (!data) {\r\n            const recoveredStudent = await findSignedInStudentRecord(user);\r\n            if (recoveredStudent) {\r\n                const adminData = await getAdminAccessData(user.uid, recoveredStudent);\r\n                const accessReason = accessErrorFor(adminData);\r\n                if (accessReason) {\r\n                    await signOut(auth).catch(() => {});\r\n                    hideAuthGate();\r\n                    showError(accessReason);\r\n                    return;\r\n                }\r\n                syncSchoolName(user.uid, recoveredStudent).catch(() => {});\r\n                saveStudentSession(buildStudentSession(user, recoveredStudent, adminData));\r\n                setAuthGate(\"Opening student dashboard...\");\r\n                window.location.href = \"#/student-dashboard.html\";\r\n                return;\r\n            }\r\n            hideAuthGate(); showError(\"User data not found. Contact admin.\"); return;\r\n        }\r\n        const role = data.role;\r\n        if (data.email && user.email && data.email.toLowerCase() !== user.email.toLowerCase()) {\r\n            hideAuthGate();\r\n            showError(\"Account mismatch detected\"); return;\r\n        }\r\n        clearStudentSession();\r\n        clearTeacherSession();\r\n        const adminData = await getAdminAccessData(user.uid, data);\r\n        const accessReason = accessErrorFor(adminData || data, role === \"admin\" ? \"dashboard\" : \"\");\r\n        if (accessReason) {\r\n            await signOut(auth).catch(() => {});\r\n            hideAuthGate();\r\n            showError(accessReason);\r\n            return;\r\n        }\r\n        syncSchoolName(user.uid, data).catch(() => {});\r\n        if (isNativeSchoolixApp() && role === \"admin\") {\r\n            await signOut(auth).catch(() => {});\r\n            hideAuthGate();\r\n            showError(\"Admin login is only available on the web panel. Please use a student, parent, teacher, librarian, or accountant account in the app.\");\r\n            return;\r\n        }\r\n        if (role === \"teacher\") {\r\n            setAuthGate(\"Opening teacher dashboard...\");\r\n            const teacherSession = buildTeacherSession(user, data, adminData, { loginAs: \"teacher\" });\r\n            saveTeacherSession(teacherSession);\r\n            window.location.href = \"#/teacher-dashboard.html\"; return;\r\n        }\r\n        if (role === \"admin\") { window.location.href = \"#/admin-dashboard.html\"; return; }\r\n        if (role === \"librarian\") { window.location.href = \"#/library-dashboard.html\"; return; }\r\n        if (role === \"accountant\") { window.location.href = \"#/accountant-dashboard.html?v=accountant-dashboard-recovery-20260806\"; return; }\r\n        if (role === \"driver\") {\r\n            setAuthGate(\"Opening driver dashboard...\");\r\n            window.location.href = \"#/driver-dashboard.html\"; return;\r\n        }\r\n        if (role === \"student\") {\r\n            setAuthGate(\"Opening student dashboard...\");\r\n            saveStudentSession(buildStudentSession(user, data, adminData, { loginAs: \"student\" }));\r\n            window.location.href = \"#/student-dashboard.html\"; return;\r\n        }\r\n        hideAuthGate();\r\n        showError(\"Invalid role assigned\");\r\n    } catch (e) { hideAuthGate(); showError(\"Login error. Try again.\"); }\r\n}\r\n\r\nloginForm.addEventListener('submit', async (e) => {\r\n    e.preventDefault();\r\n    const identifier = emailInput.value.trim();\r\n    const password = passwordInput.value.trim();\r\n    if (!identifier || !password) { showError('Please fill all fields'); return; }\r\n    showLoading(true);\r\n\r\n    const looksLikeEmail = identifier.includes(\"@\") || identifier.toLowerCase().includes(\".com\") || identifier.toLowerCase().includes(\".in\");\r\n\r\n    try {\r\n        let directAuthError = null;\r\n        if (looksLikeEmail) {\r\n            try {\r\n                const authId = identifier.toLowerCase();\r\n                const cred = await signInWithEmailAndPassword(auth, authId, password);\r\n                await checkUserRoleAndRedirect(cred.user);\r\n                return;\r\n            } catch (error) {\r\n                directAuthError = error;\r\n            }\r\n        }\r\n\r\n        let studentLogin = { success: false, reason: \"\" };\r\n        try {\r\n            studentLogin = await loginStudent(identifier, password);\r\n            if (studentLogin.success) return;\r\n        } catch (studentAuthError) {\r\n            studentLogin.reason = studentAuthError.code === \"auth/wrong-password\" || studentAuthError.code === \"auth/invalid-credential\"\r\n                ? \"Wrong student password\"\r\n                : studentAuthError.code === \"auth/user-not-found\"\r\n                    ? \"No login account found for this student. Contact admin.\"\r\n                    : studentAuthError.message;\r\n        }\r\n\r\n        const authError = directAuthError || new Error(studentLogin.reason || \"Login failed\");\r\n        showError(studentLogin.reason || userFacingAuthError(authError));\r\n    } catch (authError) {\r\n        showError(userFacingAuthError(authError));\r\n    } finally { showLoading(false); }\r\n});\r\n\r\nasync function finishGoogleLogin(user) {\r\n    if (!user) return false;\r\n    authRedirectInProgress = true;\r\n    try {\r\n        await checkUserRoleAndRedirect(user);\r\n    } finally {\r\n        setTimeout(() => { authRedirectInProgress = false; }, 1500);\r\n    }\r\n    return true;\r\n}\r\n\r\n\r\nasync function handleGoogleRedirectResult() {\r\n    try {\r\n        const result = await getRedirectResult(auth);\r\n        if (result?.user) {\r\n            setAuthGate(\"Opening your dashboard...\");\r\n            await finishGoogleLogin(result.user);\r\n        }\r\n    } catch (error) {\r\n        hideAuthGate();\r\n        showError(userFacingAuthError(error, \"Google login failed. Please try again.\"));\r\n    }\r\n}\r\n\r\nwindow.loginWithGoogle = async () => {\r\n    showLoading(true);\r\n    try {\r\n        if (isNativeSchoolixApp() && window.SchoolixNativeAuth?.signInWithGoogle) {\r\n            const result = await signInWithNativeGoogle();\r\n            await finishGoogleLogin(result.user);\r\n            return;\r\n        }\r\n        const result = await signInWithPopup(auth, googleProvider);\r\n        await finishGoogleLogin(result.user);\r\n    } catch (e) {\r\n        const code = String(e?.code || \"\");\r\n        if (code.includes(\"popup\") || code.includes(\"cancelled\") || code.includes(\"operation-not-supported\")) {\r\n            try {\r\n                await signInWithRedirect(auth, googleProvider);\r\n                return;\r\n            } catch (redirectError) {\r\n                showError(userFacingAuthError(redirectError, \"Google login failed. Please try again.\"));\r\n            }\r\n        } else {\r\n            showError(userFacingAuthError(e, \"Google login failed. Please try again.\"));\r\n        }\r\n    } finally { showLoading(false); }\r\n};\r\n\r\nwindow.resetPassword = async () => {\r\n    const identifier = emailInput.value.trim();\r\n    if (!identifier) { showError('Please enter your email or Student ID first'); return; }\r\n    showLoading(true);\r\n    try {\r\n        let emailToReset = identifier;\r\n        if (!identifier.includes(\"@\")) {\r\n            const student = await findStudentRecord(identifier, { parent: true });\r\n            if (!student) { showError('Student record not found'); return; }\r\n            emailToReset = String(student.authEmail || student.email || \"\").trim();\r\n            if (!emailToReset || emailToReset.endsWith(\"@schoolix.student\")) {\r\n                showError('No registered email found for this student. Contact admin.');\r\n                return;\r\n            }\r\n        }\r\n        await requestPasswordResetEmail(emailToReset);\r\n        showError('Password reset email sent to your registered address');\r\n    } catch (e) {\r\n        showError(userFacingAuthError(e, \"Password reset email failed. Contact admin.\"));\r\n    } finally { showLoading(false); }\r\n};\r\n\r\nhandleGoogleRedirectResult();\r\n\r\nonAuthStateChanged(auth, async (user) => {\r\n    if (authRedirectInProgress) return;\r\n    if (user) { await checkUserRoleAndRedirect(user); return; }\r\n    const savedStudentSession = loadStudentSession();\r\n    if (savedStudentSession) {\r\n        clearStudentSession();\r\n        showError(\"Your saved session expired. Please sign in again.\");\r\n    }\r\n    hideAuthGate();\r\n});\r\n"},{"attributes":{"src":"schoolix-polish.js"},"text":""}]};
